              text: 'NOUNS name people, places, things and ideas.\n\nCOMMON NOUNS: billabong, wombat, storm, courage\nPROPER NOUNS (capital letters): Sydney, Murray River, Naidoc Week, Australia\nABSTRACT NOUNS (ideas and feelings): freedom, hope, kindness\nCOLLECTIVE NOUNS: a mob of kangaroos, a colony of bats, a flock of corellas\n\nTEST: Can you put "the" in front of it? The wombat, the storm, the river. ✓',
