              label: '👂 Active Listening Skills',
              text: 'ACTIVE LISTENING means:\n\nATTENTION:\n✓ Face the speaker\n✓ Make eye contact\n✓ Avoid side conversations\n\nENGAGEMENT:\n✓ Nod or show reactions\n✓ Notice key points\n\nFOLLOW-UP:\n✓ Ask clarifying questions: "What do you mean by...?"\n✓ Connect to what was said: "That relates to what I was thinking..."\n\nIMPORTANT: Active listening is NOT passive agreement — you can actively listen and then respectfully disagree.',
              highlight: 'blue',
