              text: 'COMMON NOUNS name general things: dog, beach, school, thought, storm.\nPROPER NOUNS name specific people, places or things (always a capital letter): "Lola", "Bondi Beach", "Australia".\nCOLLECTIVE NOUNS name groups: "a mob of kangaroos", "a pack of dogs", "a flock of corellas".\n\nTest to find a noun: Can you put "the" or "a" in front of it? "a beach" ✓ "a runs" ✗ → runs is not a noun.\n\nEXAMPLES IN SENTENCES:\n"The [dingo] drank from the [waterhole] near [Uluru]." (three nouns — common, common, proper)',
