        teacherNote: 'Ask students: "If I say \'he runs to the oval and then he stopped\' — what\'s wrong?" They\'ll hear it. That\'s the goal: develop an EAR for tense inconsistency. Tense consistency is about serving the reader — you want them to know clearly WHEN events happen.',
