              label: '🔍 Step-by-Step Tense Check',
              text: 'STEP 1 — Decide your tense before you write.\nMost NARRATIVES (stories about events): past tense\nMost PROCEDURES (how to do something): present tense\nMost REPORTS/INFORMATION TEXTS: present tense\n\nSTEP 2 — Find every verb when you proofread.\nVerbs are the "doing/being/having" words: ran, is, seems, felt, explains, will go.\n\nSTEP 3 — Check each verb against your chosen tense.\nPAST: ran ✓ / runs ✗\nPRESENT: runs ✓ / ran ✗\n\nSTEP 4 — Fix by changing the verb form.\nPresent → Past: run→ran, see→saw, write→wrote, is→was, are→were, eat→ate\nPast → Present: ran→runs, saw→sees, wrote→writes, was→is, were→are, ate→eats',
