        teacherNote: 'Use the FANBOYS acronym as a memory tool — students enjoy checking off each letter. For subordinating conjunctions, stress that the dependent clause CANNOT stand alone: "Because she was late" is not a sentence on its own — it needs a main clause.',
        imagePrompt: 'A three-section classroom grammar poster: section 1 shows FANBOYS with examples in speech bubbles; section 2 shows subordinating conjunctions with a "main clause + dependent clause" diagram; section 3 shows connective adverbs linking two sentences, Year 4 style.',
